        assert_eq!(custom.1, "");
        assert_eq!(custom.2, "");
        assert_eq!(custom.3, "[]");
        assert_eq!(custom.4, "");
        assert_eq!(custom.5, "");
        assert!(custom.6.starts_with("rovai://member-avatar/managed/"));
        assert_eq!(custom.7, 17);
        assert!(custom.8.contains("memory.write"));

