    #[test]
    fn v52_migrates_legacy_ids_to_uuid_keyed_profiles_and_one_monotonic_namespace() {
        let directory = std::env::temp_dir().join(format!("rovai-db-v52-test-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&directory).expect("temporary database directory should exist");
        let path = directory.join("rovai.sqlite");
        let connection = Connection::open(&path).expect("legacy database should open");
        connection
            .execute_batch(
                r#"
                PRAGMA foreign_keys = ON;
                CREATE TABLE schema_migration (
                    version INTEGER PRIMARY KEY,
                    applied_at TEXT NOT NULL
                );
                CREATE TABLE adapter_installation(id TEXT PRIMARY KEY);
                CREATE TABLE agent_profile (
                    id TEXT PRIMARY KEY,
                    slug TEXT NOT NULL UNIQUE,
                    display_name TEXT NOT NULL,
                    accent TEXT NOT NULL,
                    runtime_enabled INTEGER NOT NULL DEFAULT 0,
                    visual_state_json TEXT NOT NULL DEFAULT '{}',
                    created_at TEXT NOT NULL,
                    updated_at TEXT NOT NULL,
                    avatar_ref TEXT,
                    default_capabilities_json TEXT NOT NULL DEFAULT '[]',
                    default_provider TEXT,
                    default_model TEXT,
                    profile_status TEXT NOT NULL DEFAULT 'present',
                    version INTEGER NOT NULL DEFAULT 1,
                    archived_at TEXT,
                    handle TEXT,
                    default_runtime_installation_id TEXT REFERENCES adapter_installation(id),
                    default_model_selection_json TEXT,
                    default_permission_config_json TEXT,
                    member_order INTEGER NOT NULL DEFAULT 0,
                    removed_at TEXT,
                    selected_runtime_adapter_kind TEXT,
                    team_role TEXT NOT NULL DEFAULT '',
                    professional_responsibilities TEXT NOT NULL DEFAULT '',
                    personality_traits_json TEXT NOT NULL DEFAULT '[]',
                    working_principles TEXT NOT NULL DEFAULT '',
                    growth_topic TEXT NOT NULL DEFAULT ''
                );
                CREATE TABLE camp(
                    id TEXT PRIMARY KEY,
                    default_lead_agent_id TEXT
                );
                CREATE TABLE conversation(
                    id TEXT PRIMARY KEY,
                    agent_id TEXT NOT NULL REFERENCES agent_profile(id),
                    native_adapter_installation_id TEXT,
                    native_session_id TEXT,
                    native_binding_compatibility_digest TEXT,
                    native_binding_id TEXT,
                    native_binding_generation INTEGER NOT NULL DEFAULT 0,
                    native_binding_secret_digest TEXT,
                    native_read_through_camp_message_sequence INTEGER NOT NULL DEFAULT 0,
                    native_charter_digest TEXT,
                    native_member_state_digest TEXT,
                    native_installation_generation INTEGER,
                    native_session_compatibility_key TEXT,
                    version INTEGER NOT NULL DEFAULT 1,
                    updated_at TEXT NOT NULL
                );
                CREATE TABLE camp_message(
                    id TEXT PRIMARY KEY,
                    addressed_agent_ids_json TEXT NOT NULL,
                    structured_content_json TEXT,
                    presentation_json TEXT,
                    content_digest TEXT NOT NULL,
                    version INTEGER NOT NULL DEFAULT 1,
                    updated_at TEXT NOT NULL
                );

                INSERT INTO agent_profile(
                    id, slug, handle, display_name, accent, member_order,
                    created_at, updated_at
                ) VALUES
                    ('agent-luoke', 'luoke', 'luoke', '小狐狸', '#1', 0, '2026-01-01', '2026-01-01'),
                    ('agent-muwa', 'muwa', 'muwa', '小河狸', '#2', 1, '2026-01-01', '2026-01-01'),
                    ('agent-mianzhi', 'mianzhi', 'mianzhi', '咕咕', '#3', 2, '2026-01-01', '2026-01-01'),
                    ('agent-qilu', 'qilu', 'qilu', '小兔', '#4', 3, '2026-01-01', '2026-01-01'),
                    ('agent-aaaaaaaa-bbbb-4ccc-8ddd-eeeeeeeeeeee', 'custom', 'custom', '自定义', '#5', 4, '2026-02-01', '2026-02-01');
                INSERT INTO camp(id, default_lead_agent_id)
                VALUES ('camp-v52', 'agent-muwa');
                INSERT INTO conversation(
                    id, agent_id, native_adapter_installation_id,
                    native_session_id, native_binding_compatibility_digest,
                    native_binding_id, native_binding_generation,
                    native_binding_secret_digest,
                    native_read_through_camp_message_sequence,
                    native_charter_digest, native_member_state_digest,
                    native_installation_generation, native_session_compatibility_key,
                    version, updated_at
                ) VALUES (
                    'conversation-v52',
                    'agent-aaaaaaaa-bbbb-4ccc-8ddd-eeeeeeeeeeee',
                    NULL, 'native-thread', 'binding-digest', 'binding-id', 2,
                    'secret-digest', 7, 'charter-digest', 'member-digest',
                    3, 'compatibility-key', 1, '2026-02-01'
                );
                INSERT INTO camp_message(
                    id, addressed_agent_ids_json,
                    structured_content_json, presentation_json,
                    content_digest, version, updated_at
                ) VALUES (
                    'message-v52',
                    '["agent-muwa","agent-aaaaaaaa-bbbb-4ccc-8ddd-eeeeeeeeeeee"]',
                    '[{"kind":"member_mention","agentId":"agent-muwa"}]',
                    '{"assigneeAgentId":"agent-aaaaaaaa-bbbb-4ccc-8ddd-eeeeeeeeeeee"}',
                    'sha256:legacy', 1, '2026-02-01'
                );
                "#,
            )
            .expect("legacy v51 fixture should be created");
        let runtime_camp_files_root = path.parent().unwrap().join("runtime-files");
        let runtime_camp_files_root_identity_digest =
            crate::camp_attachment_view::runtime_root_identity_digest_for_database(
                &runtime_camp_files_root,
            )
            .unwrap();
        let mut database = Database {
            connection,
            path,
            runtime_camp_files_root,
            runtime_camp_files_root_identity_digest,
        };

        database
            .migrate_agent_identity_v52()
            .expect("v52 migration should succeed");

        let profiles = database
            .connection()
            .prepare("SELECT uuid, id FROM agent_profile ORDER BY member_order")
            .unwrap()
            .query_map([], |row| {
                Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
            })
            .unwrap()
            .collect::<rusqlite::Result<Vec<_>>>()
            .unwrap();
        assert_eq!(
            profiles
                .iter()
                .map(|(_, id)| id.as_str())
                .collect::<Vec<_>>(),
            ["agent_1", "agent_2", "agent_3", "agent_4", "agent_5"]
        );
        assert!(
            profiles
                .iter()
                .all(|(uuid, _)| Uuid::parse_str(uuid).is_ok())
        );
        assert_eq!(
            database.agent_id_aliases().unwrap().get("agent-muwa"),
            Some(&"agent_2".to_string())
        );
        assert_eq!(
            database
                .agent_id_aliases()
                .unwrap()
                .get("agent-aaaaaaaa-bbbb-4ccc-8ddd-eeeeeeeeeeee"),
            Some(&"agent_5".to_string())
        );
        let lead: String = database
            .connection()
            .query_row(
                "SELECT default_lead_agent_id FROM camp WHERE id = 'camp-v52'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(lead, "agent_2");
        let conversation: (String, Option<String>, i64) = database
            .connection()
            .query_row(
                "SELECT agent_id, native_session_id, native_binding_generation FROM conversation",
                [],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .unwrap();
        assert_eq!(conversation, ("agent_5".to_string(), None, 0));
        let message: (String, String, String) = database
            .connection()
            .query_row(
                "SELECT addressed_agent_ids_json, structured_content_json, presentation_json FROM camp_message",
                [],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .unwrap();
        assert_eq!(message.0, r#"["agent_2","agent_5"]"#);
        assert!(message.1.contains("agent_2"));
        assert!(message.2.contains("agent_5"));
        let transaction = database.connection_mut().transaction().unwrap();
        assert_eq!(
            crate::agent_identity::allocate_agent_id(&transaction).unwrap(),
            "agent_6"
        );
        transaction.commit().unwrap();

        drop(database);
        std::fs::remove_dir_all(directory).expect("temporary database should be removable");
    }

    #[test]
    fn current_schema_contains_required_contract_objects() {
        let directory =
            std::env::temp_dir().join(format!("rovai-current-schema-test-{}", Uuid::new_v4()));
        let database = crate::test_support::fresh_schema_database_fast_at(&directory);
        let connection = database.connection();

        assert_migrations_applied(
            connection,
            &[
                58, 59, 60, 61, 62, 67, 88, 89, 90, 91, 92, 93, 94, 95, 96, 97, 98, 99, 100, 101,
                102,
            ],
        );
        assert_schema_objects(
            connection,
            "table",
            &[
                "message_delivery",
                "message_delivery_attempt",
                "message_delivery_retry",
                "context_manifest",
                "runtime_input_delivery",
                "runtime_usage_collection_state",
                "runtime_usage_run_summary",
                "runtime_usage_hourly",
                "runtime_cost_reconciliation_bucket",
                "runtime_usage_checkpoint",
                "skill_projection_run_registration",
                "camp_attachment_view",
                "camp_attachment_view_entry",
                "camp_attachment_view_operation",
                "camp_attachment_view_operation_entry",
                "camp_attachment_publication_resolution",
            ],
            true,
        );
        let legacy_objects = [
            "camp_summary",
            "camp_summary_frontier",
            "context_compaction_attempt",
            "context_compaction_waiter",
            "context_summary_config",
            "camp_summary_fts",
            "message_delivery_context_manifest",
            "monitoring_collection_state",
            "monitoring_run_enrollment",
            "runtime_usage_raw_observation",
        ];
        assert_schema_objects(connection, "table", &legacy_objects, false);
        assert_schema_objects(connection, "view", &legacy_objects, false);
        assert_schema_objects(
            connection,
            "index",
            &[
                "message_delivery_gather_capture_source_idx",
                "message_delivery_projection_gate_idx",
                "camp_attachment_publication_revision_unique",
                "camp_attachment_publication_writer_intent_idx",
                "message_attachment_runtime_projection_idx",
            ],
            true,
        );

        assert_table_columns(
            connection,
            "conversation",
            &["last_accepted_public_boundary_sequence"],
            &["native_read_through_camp_message_sequence"],
        );
        assert_table_columns(
            connection,
            "context_manifest",
            &[
                "previous_accepted_public_boundary_sequence",
                "context_delivery_profile_version",
                "context_delivery_profile_json",
                "context_delivery_profile_digest",
                "originating_public_user_message_ref_json",
                "recent_message_refs_json",
                "omitted_message_count",
                "omitted_message_sequence_start",
                "omitted_message_sequence_end",
                "shared_message_evidence_json",
                "shared_message_evidence_digest",
                "run_fact_payload_json",
                "run_fact_refs_json",
                "run_fact_digest",
            ],
            &["camp_summary_ids_json", "coverage_baseline_sequence"],
        );
        assert_table_columns(
            connection,
            "camp_message",
            &[
                "structured_content_json",
                "effective_recipient_ids_json",
                "recipient_set_digest",
                "recipient_presentation_json",
                "source_operation_id",
            ],
            &[],
        );
        assert_table_columns(
            connection,
            "camp",
            &["activation_state"],
            &["status", "archived_at"],
        );
        assert_table_columns(connection, "agent_run", &["runtime_observed_model_id"], &[]);
        assert_table_columns(
            connection,
            "skill_projection_observation",
            &["operation_id", "entry_identity"],
            &[],
        );
        assert_table_columns(
            connection,
            "skill_projection_run_registration",
            &[
                "agent_run_id",
                "execution_epoch",
                "execution_root",
                "root_identity",
                "registered_at",
            ],
            &[],
        );
        assert_table_columns(
            connection,
            "camp_attachment_view",
            &[
                "catalog_revision",
                "semantic_catalog_digest",
                "semantic_revision",
                "resolved_revision",
                "resolution_digest",
            ],
            &[],
        );
        assert_table_columns(
            connection,
            "camp_attachment_view_operation",
            &[
                "source_kind",
                "camp_message_id",
                "semantic_revision",
                "resolution_state",
                "resolution_ledger_digest",
                "terminal_failure_code",
            ],
            &[],
        );
        assert_table_columns(
            connection,
            "message_attachment",
            &[
                "runtime_projection_state",
                "publication_operation_id",
                "publication_semantic_revision",
            ],
            &[],
        );
        assert_table_columns(
            connection,
            "message_delivery",
            &["pre_dispatch_gate", "projection_operation_id"],
            &[],
        );
        assert_table_columns(
            connection,
            "camp_attachment_view_entry",
            &["published_catalog_revision"],
            &[],
        );
        assert_schema_objects(
            connection,
            "index",
            &[
                "skill_projection_operation_unique",
                "skill_projection_run_registration_root_idx",
            ],
            true,
        );
        assert_schema_objects(
            connection,
            "trigger",
            &[
                "context_manifest_v21_only_insert",
                "context_manifest_version_immutable",
                "runtime_input_delivery_attachment_auth_insert",
                "camp_attachment_view_camp_insert",
            ],
            true,
        );
        assert_schema_objects(
            connection,
            "trigger",
            &["context_manifest_v20_only_insert"],
            false,
        );

        let manifest_schema: String = connection
            .query_row(
                "SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'context_manifest'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert!(manifest_schema.contains("formatter_version = 20"));
        assert!(manifest_schema.contains("message_projection_audience TEXT NOT NULL"));
        assert!(manifest_schema.contains("a2a_guidance_evidence_json TEXT NOT NULL"));
        assert!(manifest_schema.contains("a2a_guidance_evidence_digest TEXT NOT NULL"));
        assert!(manifest_schema.contains("CHECK(context_delivery_profile_version = 4)"));
        assert!(manifest_schema.contains("collaboration_state_included INTEGER NOT NULL"));
        let delivery_schema: String = connection
            .query_row(
                "SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'runtime_input_delivery'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert!(delivery_schema.contains("CHECK(bootstrap_redelivery_envelope_version = 2)"));
        assert!(delivery_schema.contains("CHECK(bootstrap_redelivery_formatter_version = 2)"));

        let contract: (String, i64) = connection
            .query_row(
                "SELECT contract_version, projection_schema_version FROM rovai_data_contract WHERE singleton = 1",
                [],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert_eq!(
            contract,
            (
                CURRENT_DATA_CONTRACT_VERSION.to_string(),
                CURRENT_PROJECTION_SCHEMA_VERSION
            )
        );
        let foreign_key_violations: i64 = connection
            .query_row("SELECT COUNT(*) FROM pragma_foreign_key_check", [], |row| {
                row.get(0)
            })
            .unwrap();
        assert_eq!(foreign_key_violations, 0);

        let structured_content_error = connection
            .execute(
                "INSERT INTO camp_message(id, structured_content_json) VALUES ('null-content', NULL)",
                [],
            )
            .expect_err("CampMessage without Structured Content must be rejected");
        assert!(
            structured_content_error
                .to_string()
                .contains("CampMessage Structured Content is required")
        );
        let runtime_error = connection
            .execute(
                "UPDATE agent_profile SET selected_runtime_adapter_kind = 'codex-cli' WHERE id = 'agent_1'",
                [],
            )
            .expect_err("partial Member Runtime Configuration must be rejected");
        assert!(
            runtime_error
                .to_string()
                .contains("Member Runtime Configuration must be complete or absent")
        );

        connection
            .execute(
                r#"
                INSERT INTO camp(
                    id, title, project_binding_kind, project_path, created_at, updated_at
                ) VALUES (
                    'current-default-active', 'Existing creation', 'quick_chat', '/quick-chat',
                    '2026-08-09T00:00:00Z', '2026-08-09T00:00:00Z'
                )
                "#,
                [],
            )
            .unwrap();
        let activation_state: String = connection
            .query_row(
                "SELECT activation_state FROM camp WHERE id = 'current-default-active'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(activation_state, "active");
        assert!(
            connection
                .execute(
                    "UPDATE camp SET activation_state = 'unknown' WHERE id = 'current-default-active'",
                    [],
                )
                .is_err()
        );

        drop(database);
        std::fs::remove_dir_all(directory).expect("temporary database should be removable");
    }

